const selectedNews = $input.all();
const allNewsItems = $('Process News').all();

const mergedNews = selectedNews.map(selected => {
  const selectedTitle = selected.json?.title;
  const reason = selected.json?.reason;

  // پیدا کردن خبر کامل با مقایسه عناوین
  const fullNews = allNewsItems.find(item => {
    const itemTitle = item.json?.title;
    if (!itemTitle || !selectedTitle) return false;

    // مقایسه 30 کاراکتر اول برای دقت بیشتر
    const compareLength = Math.min(30, itemTitle.length, selectedTitle.length);
    return (
      itemTitle.substring(0, compareLength) === selectedTitle.substring(0, compareLength) ||
      itemTitle.includes(selectedTitle.substring(0, 20)) ||
      selectedTitle.includes(itemTitle.substring(0, 20))
    );
  });

  if (fullNews) {
    return {
      json: {
        ...fullNews.json,
        aiReason: reason
      }
    };
  }
  return selected;
});

console.log(`Merged news count: ${mergedNews.length}`);

return mergedNews;

const response = $('AI Select Top 5 News').item.json.output;
let content = typeof response === 'string' ? response : (response.text || response.content || JSON.stringify(response));

let selectedNews;
try {
  // حذف markdown code blocks
  content = content.replace(/```json\n?|```\n?/g, '').trim();
  selectedNews = JSON.parse(content);
  if (!Array.isArray(selectedNews)) {
    selectedNews = [selectedNews];
  }
} catch (error) {
  console.error('Parse error:', error);
  console.error('Content:', content);
  selectedNews = [];
}

console.log(`Selected news count: ${selectedNews.length}`);

// اطمینان از داشتن دقیقاً 5 خبر
return selectedNews.slice(0, 5).map(news => ({ json: news }));

const allNews = $input.all();
const newsText = allNews.map((item, index) => 
  `خبر ${index + 1}:
عنوان: ${item.json.title}
متن: ${item.json.content}
منبع: ${item.json.source}
دلیل انتخاب: ${item.json.aiReason || 'ندارد'}`
).join('\n\n━━━━━━━━━━━━━━━━\n\n');

return [{ 
  json: { 
    newsText, 
    newsItems: allNews.map(item => item.json),
    newsCount: allNews.length
  } 
}];

const allNews = $input.all();
const persianDate = new Date().toLocaleDateString('fa-IR', { 
  year: 'numeric', 
  month: 'long', 
  day: 'numeric', 
  weekday: 'long' 
});

let message = `📱 *اخبار برگزیده فناوری*\n🗓 ${persianDate}\n\n━━━━━━━━━━━━━━━━\n\n`;

const emojis = ['1️⃣', '2️⃣', '3️⃣', '4️⃣', '5️⃣'];

allNews.forEach((item, index) => {
  const news = item.json;
  message += `${emojis[index] || '🔹'} *${news.title}*\n\n`;
  message += `${news.summary}\n\n`;
  message += `📰 منبع: ${news.source}\n`;
  message += `🔗 [ادامه مطلب](${news.link})\n\n`;
  message += `━━━━━━━━━━━━━━━━\n\n`;
});

message += `✨ _این خبرنامه با هوش مصنوعی تهیه شده است_\n`;
message += `⏰ ${new Date().toLocaleTimeString('fa-IR')}\n`;
message += `📊 انتخاب شده از بین تمام منابع خبری`;

console.log(`Final message length: ${message.length} chars`);

return [{ json: { message, newsCount: allNews.length } }];

const response = $('AI Summarize News').item.json.output;
const newsItems = $('Prepare for Summary').item.json.newsItems;

let summaries;
try {
  let content = typeof response === 'string' ? response : (response.text || response.content || JSON.stringify(response));
  content = content.replace(/```json\n?|```\n?/g, '').trim();
  summaries = JSON.parse(content);
  if (!Array.isArray(summaries)) summaries = [summaries];
} catch (error) {
  console.error('Parse error:', error);
  console.error('Content:', response);
  summaries = [];
}

// ترکیب خلاصه‌ها با اخبار اصلی
const mergedNews = newsItems.map((news, index) => {
  const matchingSummary = summaries.find(s => 
    s.title && news.title && 
    (s.title.includes(news.title.substring(0, 20)) || 
     news.title.includes(s.title.substring(0, 20)))
  ) || summaries[index];

  return {
    json: {
      ...news,
      summary: matchingSummary?.summary || news.description || 'خلاصه در دسترس نیست'
    }
  };
});

console.log(`Final news with summaries: ${mergedNews.length}`);

return mergedNews;

const allItems = $input.all();
const currentDate = new Date();
const oneDayAgo = new Date(currentDate - 24 * 60 * 60 * 1000);

let newsItems = [];
// استخراج داده‌ها با توجه به ساختار Merge
for (const item of allItems) {
  // چک میکنیم دیتای RSS مستقیم است یا داخل آرایه
  if (item.json.title && item.json.link) {
      newsItems.push(item.json);
  } else if (item.json.data && Array.isArray(item.json.data)) {
      newsItems = newsItems.concat(item.json.data);
  }
}

const recentNews = newsItems.filter(item => {
  const pubDate = new Date(item.pubDate || item.isoDate);
  return pubDate > oneDayAgo;
});

const enrichedNews = recentNews.map((item, index) => ({
  id: `news_${Date.now()}_${index}`,
  title: item.title || 'بدون عنوان',
  link: item.link || item.url || '',
  description: (item.contentSnippet || item.description || '').substring(0, 150),
  content: (item['content:encoded'] || item.content || item.description || '').substring(0, 1500),
  pubDate: item.pubDate || item.isoDate,
  source: extractSource(item.link)
}));

function extractSource(url) {
  if (!url) return 'نامشخص';
  if (url.includes('zoomit.ir')) return 'زومیت';
  if (url.includes('digiato.com')) return 'دیجیاتو';
  if (url.includes('techrato.com')) return 'تکراتو';
  if (url.includes('gadgetnews.net')) return 'گجت نیوز';
  return 'نامشخص';
}

// محدود کردن کل لیست به 40 خبر برای ارسال به هوش مصنوعی
const limitedNews = enrichedNews.slice(0, 40);

console.log(`Total items merged: ${newsItems.length}`);
console.log(`Recent news (24h): ${recentNews.length}`);

return limitedNews.map(news => ({ json: news }));
